  bool CaptureEngineering(){try{TrainStrength.Validate(document);if(document.SharedHousing!=null&&new[]{document.SharedHousing.Wall,document.SharedHousing.Partition,document.SharedHousing.Clearance,document.SharedHousing.BoltDiameter}.Any(v=>!MechanismCad.Finite(v)))throw new Exception("Параметры общего корпуса должны быть конечными числами.");return true;}catch(Exception ex){Error(ex.Message);return false;}}
  void EnsureMaterials(){if(document.Materials==null)document.Materials=new TrainMaterialSettings();}
  void StrengthReport(bool csv){Calculate();if(solution==null||solution.Strength==null){Error("Сначала включите общий корпус и назначьте материалы или нагрузку.");return;}using(var d=new SaveFileDialog{Filter=csv?"CSV|*.csv":"Text|*.txt",FileName=csv?"Перегрузка.csv":"Перегрузка.txt"})if(d.ShowLocalizedDialog(this)==DialogResult.OK)ReleaseSupport.WriteText(d.FileName,TrainStrength.Report(solution.Strength,csv),System.Text.Encoding.UTF8);}
  static string Short(double v){double a=Math.Abs(v);return Engine.F(Math.Round(v,a>=100?0:a>=10?1:2));}
  static string Value(double? value,string unit){return value.HasValue?Engine.F(value.Value)+(string.IsNullOrEmpty(unit)?"":" "+unit):"Не определено";}

  // Карточка материала: значения в поля, образец и описание вида.
  void ShowMaterial(TrainMaterial m){bool was=updatingEngineering;updatingEngineering=true;try{materialName.Text=m.Name;materialKind.Set(new[]{new Pick{Key="FDM",Text="Печать FDM"},new Pick{Key="Metal",Text="Металл"},new Pick{Key="Polymer",Text="Покупной полимер"}},null);foreach(Pick p in materialKind.Box.Items)if(p.Key==m.Kind)materialKind.Box.SelectedItem=p;
    var typical=MaterialLook.Typical(m.Name,m.Kind);var finishes=new List<object>{new Pick{Key="",Text="Типичная ("+typical.FinishName+")"}};for(int i=0;i<MaterialLook.Finishes.Length;i++)finishes.Add(new Pick{Key=MaterialLook.Finishes[i],Text=MaterialLook.FinishNames[i]});materialFinish.Set(finishes,null);foreach(Pick p in materialFinish.Box.Items)if(p.Key==(m.Finish??""))materialFinish.Box.SelectedItem=p;
    materialColorValue=string.IsNullOrWhiteSpace(m.Color)?null:m.Color.Trim();var look=MaterialLook.For(m);materialPreview.Look=look;materialPreview.Invalidate();materialLookText.Text=I18n.T(m.Kind=="FDM"?"Печать FDM":m.Kind=="Metal"?"Металл":"Покупной полимер")+" · "+I18n.T(look.FinishName)+(materialColorValue==null?" · "+I18n.T("типичный цвет"):" · "+materialColorValue);
    materialNumbers["Density"].Value=m.Density;materialNumbers["Yield"].Value=m.Yield;materialNumbers["Tensile"].Value=m.Tensile;materialNumbers["Shear"].Value=m.Shear;materialNumbers["Elastic"].Value=m.Elastic;materialNumbers["LayerFactor"].Value=m.LayerFactor;materialNumbers["Friction"].Value=m.Friction;materialNumbers["MaxTemp"].Value=m.MaxTemp;materialSource.Text=m.Source;}finally{updatingEngineering=was;}}
  // Собирает материал из формы, проверяет и применяет (правка встроенного создаёт свою копию с тем же именем).
  void CommitMaterial(){if(updatingEngineering||editedMaterial==null)return;try{var all=MaterialLibrary.Resolve(document);var old=all.FirstOrDefault(x=>x.Name==editedMaterial);if(old==null)return;var m=MaterialLibrary.Clone(old);double? v;
    m.Name=materialName.Text.Trim();var kind=materialKind.Box.SelectedItem as Pick;if(kind!=null)m.Kind=kind.Key;var finish=materialFinish.Box.SelectedItem as Pick;m.Finish=finish==null||finish.Key==""?null:finish.Key;m.Color=materialColorValue;
    foreach(var pair in materialNumbers)if(!pair.Value.TryRead(out v))throw new Exception(I18n.T("Проверьте поле: ")+I18n.T(pair.Value.Title));
    m.Density=materialNumbers["Density"].Value.Value;m.LayerFactor=materialNumbers["LayerFactor"].Value.Value;m.Yield=materialNumbers["Yield"].Value;m.Tensile=materialNumbers["Tensile"].Value;m.Shear=materialNumbers["Shear"].Value;m.Elastic=materialNumbers["Elastic"].Value;m.Friction=materialNumbers["Friction"].Value;m.MaxTemp=materialNumbers["MaxTemp"].Value;m.Source=materialSource.Text;
    MaterialLibrary.Validate(m);if(m.Name!=editedMaterial&&all.Any(x=>x.Name==m.Name))throw new Exception("Материал с таким именем уже есть: "+m.Name);
    if(CADDocument.Serializer().Serialize(m)==CADDocument.Serializer().Serialize(old)){ShowMaterial(m);return;}
    EnsureMaterials();document.Materials.Custom.RemoveAll(x=>x.Name==editedMaterial||x.Name==m.Name);document.Materials.Custom.Add(m);foreach(var dict in new[]{document.Materials.Roles,document.Materials.Parts})foreach(var key in dict.Keys.ToArray())if(dict[key]==editedMaterial)dict[key]=m.Name;if(document.Overload!=null&&document.Overload.FrictionMaterial==editedMaterial)document.Overload.FrictionMaterial=m.Name;editedMaterial=m.Name;ShowMaterial(m);Changed();}catch(Exception ex){Error(ex.Message);}}
  void CommitLoad(){if(updatingEngineering)return;double? v;foreach(var f in loadFields.Values)if(!f.TryRead(out v)){Error(I18n.T("Проверьте поле: ")+I18n.T(f.Title));return;}var l=document.OutputLoad==null?new TrainOutputLoad():CADDocument.Serializer().Deserialize<TrainOutputLoad>(CADDocument.Serializer().Serialize(document.OutputLoad));
