  void ShowEngineering(TrainSolution s){if(materialAssignments==null)return;if(s.Compound==null&&CompoundReducer.Enabled(document))return;engineeringSolution=s;updatingEngineering=true;try{var all=MaterialLibrary.Resolve(document);
    foreach(string role in Roles){string name;bool set=document.Materials!=null&&document.Materials.Roles.TryGetValue(role,out name);string current=set?document.Materials.Roles[role]:LegacyChoice;var items=new List<object>{new Pick{Key=LegacyChoice,Text="Не назначен"}};items.AddRange(all.Select(m=>(object)new Pick{Key=m.Name,Text=m.Name}));roleChoices[role].Set(items,null);foreach(Pick p in roleChoices[role].Box.Items)if(p.Key==current)roleChoices[role].Box.SelectedItem=p;var mat=all.FirstOrDefault(m=>m.Name==current);roleSwatches[role].Look=mat==null?null:MaterialLook.For(mat);roleSwatches[role].Invalidate();}
    var col=(DataGridViewComboBoxColumn)materialAssignments.Columns[1];col.Items.Clear();col.Items.AddRange(new[]{ByRoleChoice}.Concat(all.Select(m=>m.Name)).ToArray());materialAssignments.Rows.Clear();int parts=0;foreach(var p in s.Scene.Model.Parts.Where(p=>!p.Reference)){string name;var row=materialAssignments.Rows[materialAssignments.Rows.Add(p.Label,document.Materials!=null&&document.Materials.Parts.TryGetValue(p.Id,out name)?name:ByRoleChoice)];row.Tag=p.Id;parts++;}partsExpander.Caption="Отдельные детали ("+parts+")";
    if(editedMaterial==null||!all.Any(m=>m.Name==editedMaterial))editedMaterial=all.Any(m=>m.Name=="PETG")?"PETG":all.First().Name;materialPicker.Set(all.Select(m=>(object)m.Name),editedMaterial);ShowMaterial(all.First(m=>m.Name==editedMaterial));
    var load=document.OutputLoad??new TrainOutputLoad();loadFields["RadialForce"].Value=load.RadialForce;loadFields["ForceOffset"].Value=load.ForceOffset;loadFields["ForceAngle"].Value=load.ForceAngle;loadFields["AxialForce"].Value=load.AxialForce;loadFields["OutputTorque"].Value=load.OutputTorque;axialSupport.Set(new object[]{new Pick{Key="Unknown",Text="Не задана"},new Pick{Key="First",Text="Первая опора"},new Pick{Key="Second",Text="Вторая опора"}},null);foreach(Pick p in axialSupport.Box.Items)if(p.Key==load.AxialSupport)axialSupport.Box.SelectedItem=p;
    var o=document.Overload??new TrainOverloadSettings{Enabled=true};overloadShow.Checked=o.Enabled;clutchToggle.Checked=o.ClutchEnabled;overloadFields["TargetTorque"].Value=o.TargetTorque;overloadFields["SpringForce"].Value=o.SpringForce;overloadFields["Surfaces"].Value=o.Surfaces;overloadFields["MeanRadius"].Value=o.MeanRadius;overloadFields["Friction"].Value=o.Friction;var fric=new List<object>{new Pick{Key="",Text="Свой коэффициент μ"}};fric.AddRange(all.Select(m=>(object)new Pick{Key=m.Name,Text=m.Name}));frictionMaterial.Set(fric,null);foreach(Pick p in frictionMaterial.Box.Items)if(p.Key==(o.FrictionMaterial??""))frictionMaterial.Box.SelectedItem=p;
    shaftTable.Rows.Clear();strengthTable.Rows.Clear();shaftPlot.Solution=s;shaftPlot.Invalidate();var r=s.Strength;var chart=new List<ModeChart.Item>();
    if(r!=null){var b=r.Shaft;shaftTable.Rows.Add("Реакции R1 / R2, Н",Engine.F(b.Reaction1)+" / "+Engine.F(b.Reaction2));shaftTable.Rows.Add("Осевые реакции, Н",Value(b.Axial1,"")+" / "+Value(b.Axial2,""));shaftTable.Rows.Add("Изгиб, Н·мм",Engine.F(b.BendingMoment));shaftTable.Rows.Add("σ изгиба / τ кручения, МПа",Engine.F(b.BendingStress)+" / "+Engine.F(b.TorsionStress));shaftTable.Rows.Add("Приведённое (Tresca), МПа",Engine.F(b.EquivalentStress));shaftTable.Rows.Add("Прогиб, мм",Value(b.Deflection,""));shaftTable.Rows.Add("Угол, рад",Value(b.Slope,""));shaftTable.Rows.Add("Запас по текучести",Value(b.YieldMargin,""));shaftTable.Rows.Add("Ресурс подшипников L10","Не определено: нет C и режима работы");
     if(document.Overload!=null&&document.Overload.ClutchEnabled){shaftTable.Rows.Add("Момент муфты, Н·м",Value(r.ClutchTorque,""));shaftTable.Rows.Add("Прижим муфты, Н",Value(r.SpringForce,""));}
     stressTile.Set(Short(b.EquivalentStress)+" "+I18n.T("МПа"),I18n.T("изгиб")+" "+Short(b.BendingStress)+" · "+I18n.T("кручение")+" "+Short(b.TorsionStress),null);marginTile.Set(b.YieldMargin.HasValue?"× "+Short(b.YieldMargin.Value):I18n.T("не определено"),b.YieldMargin.HasValue?(b.YieldMargin.Value<1?"вал потечёт":b.YieldMargin.Value<2?"мало запаса":"с запасом"):"задайте предел текучести вала",b.YieldMargin.HasValue?(b.YieldMargin.Value<1?"Error":b.YieldMargin.Value<2?"Warning":"Success"):null);deflectionTile.Set(b.Deflection.HasValue?Short(b.Deflection.Value)+" "+I18n.T("мм"):I18n.T("не определено"),b.Slope.HasValue?I18n.T("угол")+" "+Engine.F(b.Slope.Value)+" "+I18n.T("рад"):"нужен модуль упругости вала",null);reactionTile.Set(Short(Math.Abs(b.Reaction1))+" / "+Short(Math.Abs(b.Reaction2))+" "+I18n.T("Н"),"сила на вылете "+Short(Math.Abs(b.Reaction1+b.Reaction2))+" Н",null);
     foreach(var m in r.Modes){var part=s.Scene.Model.Parts.FirstOrDefault(p=>p.Id==m.Part);var stage=document.Stages.FirstOrDefault(n=>n.Id==m.Part);string label=part!=null?part.Label:stage!=null?stage.Name:m.Part;int row=strengthTable.Rows.Add(I18n.T(m.Mode),label,Value(m.LimitTorque,""),Value(m.Margin,""),I18n.T(m.Formula));strengthTable.Rows[row].Cells[1].ToolTipText=m.Part;strengthTable.Rows[row].Cells[4].ToolTipText=I18n.T(m.Note);chart.Add(new ModeChart.Item{Mode=m.Mode,Part=label,PartId=part!=null?part.Id:null,Limit=m.LimitTorque,Formula=m.Formula,Note=m.Note});}}
    else foreach(var t in new[]{stressTile,marginTile,deflectionTile,reactionTile})t.Set("—","нужен общий корпус и нагрузка",null);
    modeChart.SetItems(chart);
    overloadVisual=new OverloadVisualState{OutputPhase=phase};var leaf=CompoundReducer.Enabled(document)?CompoundReducer.Ordered(document).Last().Id:"";foreach(var pair in s.Scene.TrainMotions){bool output=document.Overload!=null&&document.Overload.ClutchEnabled?pair.Key=="SH_CLUTCH_OUTPUT":pair.Key.EndsWith("_SH_OUTPUT_CARRIER")||pair.Key.StartsWith(leaf+"_")&&pair.Key.Contains("OUTPUT_PIN");pair.Value.Visual=output?overloadVisual:null;}overloadTorque.Enabled=r!=null&&r.LimitTorque.HasValue;ApplyOverload();}finally{updatingEngineering=false;}UpdateViewerHost();}

  void ApplyOverload(){var s=engineeringSolution;if(s==null||s.Strength==null){if(overloadStatus!=null){overloadHeadline.Set(I18n.T("Предел не определён"),"Muted");overloadStatus.Text=I18n.T("Включите общий корпус и назначьте материалы на вкладке «Материалы».");torqueGauge.Limit=null;torqueGauge.Invalidate();}return;}
   var r=s.Strength;double torque=r.LimitTorque.HasValue?r.LimitTorque.Value*overloadTorque.Value/1000:0;bool enabled=document.Overload==null||document.Overload.Enabled;double? threshold=r.LimitTorque;bool clutch=document.Overload!=null&&document.Overload.ClutchEnabled&&r.ClutchTorque.HasValue;if(clutch)threshold=threshold.HasValue?Math.Min(threshold.Value,r.ClutchTorque.Value):r.ClutchTorque;
   overloadVisual.Enabled=enabled;overloadVisual.Failed=threshold.HasValue&&torque>threshold.Value;overloadVisual.Smooth=clutch&&(!r.LimitTorque.HasValue||r.ClutchTorque<=r.LimitTorque);
   // Окраска: запас ≥ 2 — свой материал; 1–2 — от жёлтого к оранжевому; < 1 — красный и свечение.
   var colors=new Dictionary<string,Color>();var glow=new HashSet<string>();if(enabled&&torque>0)foreach(var p in s.Scene.Model.Parts){var limits=r.Modes.Where(m=>m.Part==p.Id&&m.LimitTorque.HasValue).Select(m=>m.LimitTorque.Value).ToArray();if(limits.Length==0)continue;double margin=limits.Min()/torque;if(margin<1){colors[p.Id]=UiPalette.Get("Error");glow.Add(p.Id);}else if(margin<2)colors[p.Id]=UiPalette.Blend(UiPalette.Get("Warning"),UiPalette.Get("Error"),Math.Max(0,Math.Min(1,(2-margin)*.6)));}
   viewer.Scene.SetEngineeringColors(colors,glow);
   var weak=r.Modes.Where(m=>m.Part==r.WeakestPart&&m.LimitTorque==r.LimitTorque).FirstOrDefault();string weakPart=weak==null?"":(s.Scene.Model.Parts.FirstOrDefault(p=>p.Id==weak.Part)==null?weak.Part:s.Scene.Model.Parts.First(p=>p.Id==weak.Part).Label);
   torqueGauge.Limit=r.LimitTorque;torqueGauge.Clutch=clutch?r.ClutchTorque:null;torqueGauge.Torque=torque;torqueGauge.Invalidate();modeChart.Torque=torque;modeChart.Invalidate();
   overloadTorqueText.Text=I18n.T("Момент на выходе")+": "+Engine.F(torque)+" "+I18n.T("Н·м")+(r.LimitTorque.HasValue?" · "+Engine.F(overloadTorque.Value/10.0)+"% "+I18n.T("предела"):"");
   if(!r.LimitTorque.HasValue)overloadHeadline.Set(I18n.T("Предел не определён"),"Muted");
   else if(torque<=0)overloadHeadline.Set(I18n.T("Выдержит до")+" "+Engine.F(r.LimitTorque.Value)+" "+I18n.T("Н·м"),"Text");
   else if(overloadVisual.Failed&&clutch&&overloadVisual.Smooth)overloadHeadline.Set(I18n.T("Муфта проскальзывает"),"Warning");
   else if(overloadVisual.Failed)overloadHeadline.Set(I18n.T("Сломается")+": "+I18n.T(weak==null?"":weak.Mode),"Error");
   else{double m=r.LimitTorque.Value/torque;overloadHeadline.Set(I18n.T("Держит")+" · "+I18n.T("запас")+" × "+Short(m),m<2?"Warning":"Success");}
   overloadStatus.Text=(weak==null?"":I18n.T("Слабое место")+": "+weakPart+"\n")+(r.ClutchTorque.HasValue?I18n.T("Муфта")+": "+Value(r.ClutchTorque,"Н·м")+" · "+I18n.T("прижим")+" "+Value(r.SpringForce,"Н")+"\n":"")+I18n.T("Схематичный показ, не моделирование разрушения. Скорость реального проскальзывания не определена.")+(r.ClutchTorque.HasValue&&r.LimitTorque.HasValue&&r.ClutchTorque>r.LimitTorque?"\n"+I18n.T("Муфта выше предела слабого звена — защиты нет."):"");
   overloadLegend.Items=new List<Tuple<Color,string>>{Tuple.Create(UiPalette.Get("Warning"),"запас 1–2"),Tuple.Create(UiPalette.Get("Error"),"сломается"),Tuple.Create(UiPalette.Get("Accent"),"момент "+Engine.F(torque)+" Н·м")};overloadLegend.Invalidate();}
  void AdvanceOverload(double delta){overloadVisual.Advance(delta);}

  // Стрелки нагрузки для 3D: радиальная сила на вылете, осевая сила и рабочий момент на выходном валу.
  List<LoadArrow> LoadArrows(bool withTorque){var s=engineeringSolution;if(s==null||s.Compound==null||s.Strength==null||s.Strength.Shaft==null)return null;var b=s.Strength.Shaft;var l=document.OutputLoad??new TrainOutputLoad();double d=Math.Max(20,s.Compound.Diameter),z=b.LoadZ;var list=new List<LoadArrow>();double a=l.ForceAngle*Math.PI/180;var dir=new System.Windows.Media.Media3D.Vector3D(Math.Cos(a),Math.Sin(a),0);
   if(l.RadialForce>0)list.Add(new LoadArrow{Origin=new System.Windows.Media.Media3D.Point3D(0,0,z),Direction=dir,Length=d*.65,Radius=Math.Max(.6,d*.022),Color=UiPalette.Get("Warning")});
   if(l.AxialForce>0)list.Add(new LoadArrow{Origin=new System.Windows.Media.Media3D.Point3D(0,0,z+d*.06),Direction=new System.Windows.Media.Media3D.Vector3D(0,0,-1),Length=d*.45,Radius=Math.Max(.6,d*.022),Color=UiPalette.Get("AxisZ")});
   if(withTorque&&s.Strength.WorkingTorque>0)list.Add(new LoadArrow{Origin=new System.Windows.Media.Media3D.Point3D(0,0,s.Compound.OutputPlane+2),Direction=new System.Windows.Media.Media3D.Vector3D(0,0,1),Length=d*.62,Radius=Math.Max(.5,d*.016),Color=UiPalette.Get("Accent"),Torque=true});return list;}
  void UpdateLoadLegend(){var s=engineeringSolution;var l=document.OutputLoad??new TrainOutputLoad();loadsLegend.Items=new List<Tuple<Color,string>>{Tuple.Create(UiPalette.Get("Warning"),"радиальная "+Engine.F(l.RadialForce)+" Н на "+Engine.F(l.ForceOffset)+" мм"),Tuple.Create(UiPalette.Get("AxisZ"),"осевая "+Engine.F(l.AxialForce)+" Н"),Tuple.Create(UiPalette.Get("Accent"),"момент "+(s!=null&&s.Strength!=null?Engine.F(s.Strength.WorkingTorque):"—")+" Н·м")};loadsLegend.Invalidate();}
 }

 // Подпись под 3D: цветной кружок и текст для каждого обозначения.
 public sealed class LegendStrip:Control {
  public List<Tuple<Color,string>> Items=new List<Tuple<Color,string>>();
  public LegendStrip(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);Height=30;}
  protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(UiPalette.Get("Panel"));g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;int x=12;foreach(var item in Items){using(var b=new SolidBrush(item.Item1))g.FillEllipse(b,x,Height/2-5,10,10);x+=16;string text=I18n.T(item.Item2);var size=TextRenderer.MeasureText(text,Font);TextRenderer.DrawText(g,text,Font,new Rectangle(x,0,size.Width+4,Height),UiPalette.Get("Muted"),TextFormatFlags.VerticalCenter|TextFormatFlags.NoPrefix);x+=size.Width+18;}}
 }
